package com.ryz.controller;
import android.app.Activity;import android.app.AlertDialog;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.view.MotionEvent;import android.widget.Button;import android.widget.EditText;import android.widget.TextView;import android.widget.Toast;
public class MainActivity extends Activity{
private ControllerClient client;private MirrorView mirrorView;private TextView tvStatus;private Button btnRestart,btnConnect;private EditText etIp;private final Handler mainHandler=new Handler(Looper.getMainLooper());
@Override protected void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_main);tvStatus=findViewById(R.id.tvStatus);btnRestart=findViewById(R.id.btnRestart);btnConnect=findViewById(R.id.btnConnect);etIp=findViewById(R.id.etIp);mirrorView=findViewById(R.id.mirrorView);
btnConnect.setOnClickListener(v->{String ip=etIp.getText().toString().trim();if(ip.isEmpty()){Toast.makeText(this,"Masukkan IP",Toast.LENGTH_SHORT).show();return;}connectToAgent(ip);});
btnRestart.setEnabled(false);btnRestart.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Restart?").setMessage("HP kedua akan direstart.").setPositiveButton("Ya",(d,w)->{if(client!=null)client.sendCommand("REBOOT");setStatus("Reboot dikirim...",false);}).setNegativeButton("Batal",null).show());
mirrorView.setOnTouchListener((v,e)->{if(client==null||!client.isConnected())return false;int a=e.getAction();float x=e.getX(),y=e.getY();float[]sc=mirrorView.scaleToAgent(x,y);if(a==MotionEvent.ACTION_DOWN){mirrorView.setSwipeStart(x,y);client.sendCommand("TAP:"+sc[0]+":"+sc[1]);}else if(a==MotionEvent.ACTION_UP){mirrorView.triggerSwipe(x,y);}else if(a==MotionEvent.ACTION_MOVE){mirrorView.trackMove(x,y);}return true;});
mirrorView.setSwipeListener((x1,y1,x2,y2)->{if(client==null)return;float[]s1=mirrorView.scaleToAgent(x1,y1),s2=mirrorView.scaleToAgent(x2,y2);client.sendCommand("SWIPE:"+s1[0]+":"+s1[1]+":"+s2[0]+":"+s2[1]+":300");});}
private void connectToAgent(String ip){setStatus("Menghubungkan ke "+ip+"...",false);btnConnect.setEnabled(false);client=new ControllerClient("ws://"+ip+":9876",()->mainHandler.post(()->{setStatus("Terhubung ke "+ip,true);btnRestart.setEnabled(true);btnConnect.setEnabled(true);client.sendCommand("INFO");}),()->mainHandler.post(()->{setStatus("Koneksi terputus",false);btnRestart.setEnabled(false);btnConnect.setEnabled(true);}),fb->mainHandler.post(()->mirrorView.updateFrame(fb)),msg->mainHandler.post(()->{if(msg.startsWith("INFO:")){String[]p=msg.split(":");mirrorView.setAgentResolution(Integer.parseInt(p[1]),Integer.parseInt(p[2]));}else if(msg.equals("REBOOT_FAILED:needs_root")){Toast.makeText(this,"Reboot gagal",Toast.LENGTH_LONG).show();}}));client.connect();}
private void setStatus(String m,boolean c){tvStatus.setText(m);tvStatus.setTextColor(c?getColor(android.R.color.holo_green_light):getColor(android.R.color.holo_red_light));}
@Override protected void onDestroy(){super.onDestroy();if(client!=null)client.disconnect();}}